python3 << 'EOF'
import re, json
txt = open('eprint/midlam.eps').read()
# strip prolog defs line
toks = txt.replace('\n',' ').split()
paths=[]   # each: dict(color, lw, pts, fill)
color=(0,0,0); lw=0; cur=[]
def flush(fill=False):
    global cur
    if len(cur)>=2:
        paths.append(dict(color=color, lw=lw, pts=list(cur), fill=fill))
    cur=[]
stack=[]
for t in toks:
    if t=='C':
        if len(stack)>=3: color=tuple(float(x) for x in stack[-3:])
        stack=[]
    elif t=='SL':
        if stack: lw=float(stack[-1])
        stack=[]
    elif t=='M':
        if len(stack)>=2:
            p=(float(stack[-2]),float(stack[-1]))
            # continue path if same point
            if cur and abs(cur[-1][0]-p[0])<1e-9 and abs(cur[-1][1]-p[1])<1e-9:
                pass
            else:
                flush()
                cur=[p]
        stack=[]
    elif t=='L':
        if len(stack)>=2 and cur:
            cur.append((float(stack[-2]),float(stack[-1])))
        stack=[]
    elif t=='CFN':
        flush(fill=True)
    elif t=='SN':
        flush()
    else:
        try: float(t); stack.append(t)
        except ValueError: stack=[]
flush()
# merge consecutive stroked paths that connect (GRAF strokes each segment separately with SN)
merged=[]
for p in paths:
    if merged:
        q=merged[-1]
        if (not p['fill'] and not q['fill'] and p['color']==q['color'] and p['lw']==q['lw']
            and abs(q['pts'][-1][0]-p['pts'][0][0])<1e-6 and abs(q['pts'][-1][1]-p['pts'][0][1])<1e-6):
            q['pts'].extend(p['pts'][1:]); continue
    merged.append(p)
print('paths:',len(merged))
# summarize long paths
for i,p in enumerate(merged):
    if len(p['pts'])>15 or p['fill']:
        xs=[a for a,b in p['pts']]; ys=[b for a,b in p['pts']]
        print(i, 'fill' if p['fill'] else 'stroke', p['color'], p['lw'], len(p['pts']),
              f"x[{min(xs):.2f},{max(xs):.2f}] y[{min(ys):.2f},{max(ys):.2f}]")
json.dump([{ 'color':p['color'],'lw':p['lw'],'fill':p['fill'],'pts':p['pts']} for p in merged], open('paths.json','w'))
EOF
